# -*- coding: utf-8 -*-
# Створення довідників Авто/Водії/Перевізники + 3 нових колонок угоди.
# ТІЛЬКИ ДОДАЄ: наявні таблиці й колонки не чіпаються (перевірка за назвою).
import json, urllib.request
TOK = open('/root/nocodb-token.txt').read().strip()
BASE = 'pbhr1qkpvx09z8m'; DISP = 'm58xsjo6at01ohl'
def nc(p, method='GET', body=None):
    r = urllib.request.Request('http://localhost:8080' + p, method=method,
        data=json.dumps(body).encode() if body is not None else None,
        headers={'xc-token': TOK, 'Content-Type': 'application/json'})
    return json.load(urllib.request.urlopen(r, timeout=30))
have = {t['title'] for t in nc('/api/v2/meta/bases/%s/tables' % BASE).get('list', [])}
def col(t, uidt='SingleLineText', **kw): return dict({'title': t, 'column_name': t, 'uidt': uidt}, **kw)
TABLES = {
  'Авто': [col('Номер'), col('Тип', 'SingleSelect', meta={}, colOptions={'options': [{'title': 'тягач'}, {'title': 'причеп'}]}), col('Перевізник'), col('Примітка')],
  'Водії': [col('ПІБ'), col('Телефон'), col('Паспорт'), col('Перевізник'), col('Примітка')],
  'Перевізники': [col('Назва'), col('Код'), col('IBAN'), col('Банк'), col('EORI'), col('Адреса'), col('Примітка')],
}
for name, cols in TABLES.items():
    if name in have:
        print('таблиця «%s» вже є — не чіпаю' % name); continue
    r = nc('/api/v2/meta/bases/%s/tables' % BASE, 'POST', {'title': name, 'table_name': name, 'columns': cols})
    print('створено таблицю «%s» → %s' % (name, r.get('id')))
dcols = {c.get('title') for c in nc('/api/v2/meta/tables/%s' % DISP).get('columns', [])}
for t in ('Причеп', 'Водій (паспорт)', 'Пункт перетину'):
    if t in dcols:
        print('колонка «%s» вже є — не чіпаю' % t); continue
    nc('/api/v2/meta/tables/%s/columns' % DISP, 'POST', {'title': t, 'column_name': t, 'uidt': 'SingleLineText'})
    print('додано колонку «%s» в Диспетчеризацію' % t)
print('ГОТОВО')
PYEOF
